var MSSCustodyBulkFileUpload = Class.create();
MSSCustodyBulkFileUpload.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /*
Schema for Bulk Level and Trade Level File upload functions

bulkLevelParse   ------>   bulkErrorValidation ------>  createBulkCaseTask  ------> Creates case and flow starts triggering due to case creation
(Reads the Excel)			(Segregation of Valid/		(Case Creation for			
                                invalid Trades)			valid trades)
                                   |
                                   |
                                   |--------------------> populateErrorRecord ------> Populates the new field (TBD) in bulk for audit


tradeLevelParse   ------>   bulkErrorValidation ------>  createBulkCaseTask  ------> Creates case and flow starts triggering due to case creation
(Reads the Excel)			(Segregation of Valid/		(Case Creation for			
                                invalid Trades)			valid trades)
                                   |
                                   |
                                   |--------------------> populateErrorRecord ------> Populates the new field (TBD) in bulk for audit
*/


    handleTradeReference: function(trdRef, trdMarket) {

        try {

            //Handling trade Reference Format

            var charRegex = /[^a-zA-Z0-9\s]/g; //removal of special characters
            var tradeRefRegex = /^[A-Z]-\d{6}-\d{2}-\d$/; //Trade Format Regex
            var possibleTradeRegex = /^[A-Z]\d{9}$/i;
            var checkFormat = tradeRefRegex.test(trdRef);
            var possiblyTrade = possibleTradeRegex.test(trdRef);

            if (((!checkFormat) && (trdMarket.indexOf('UK') == -1)) || ((possiblyTrade) && (trdMarket.indexOf('UK') > -1))) { //checking if the trade is not in format of R-655012-00-0 else formatting the trade reference and if trade is from GHSS

                trdRef = trdRef.replace(/\s/g, ""); //remove any spaces inbetween
                trdRef = trdRef.replace(charRegex, ''); //remove any special characters
                trdRef = trdRef.trim();
                var tradeSec1 = trdRef.substring(0, 1);
                var tradeSec2 = trdRef.substring(1, 7);
                var tradeSec3 = trdRef.substring(7, 9);
                var tradeSec4 = trdRef.substring(9, 11);
                var generatedTradeRef = tradeSec1 + "-" + tradeSec2 + "-" + tradeSec3 + "-" + tradeSec4;
                trdRef = generatedTradeRef; //formatted version

            } else { //if GHSS and UK owning business selected

                trdRef = trdRef.trim(); //handling for UK trade

            }


            return trdRef;
            //Handling Trade Reference Format

        } catch (ex) {

            gs.info('Error received from File Upload handleTradeReference ' + ex);

        }

    },



    //Widgets
    //Bulk Level Fil Upload
    validateBulkFileUpload: function() {

        /* The array of invalid trades received from bulkErrorValidation 
        will be utilized to populate the new field(TBD) in submitted bulk which will be utilized for the display of audit log*/

        try {
            //gs.info('Bulk Validation File read - started for 500 records at ' + new GlideDateTime().getDisplayValue());
            var owningBusiness = this.getParameter('sysparm_market');
            var outcomeSelected = this.getParameter('sysparm_outcome');
            var bulkexcelRowArray = [];
            var errorObj = {};
            var errorRecords = [];
            var validRecords = [];
            var bulkFileUploadLogs = [];
            var count = 0;
            var filterArray = new global.ArrayUtil();
            var reasonCodeOutcome = '';
            var bpiOutcome = '';
            var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
            var errorRate = parseFloat(gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadErrorRateAcceptance'));
            var maxLimit = parseInt(gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadMaxUploadLimit'));
            var bulkUploadErrorLogs = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadLogs');
            var rejectionReasons = gs.getProperty('x_hsb11_hsbc_mss_o.bulkFileUploadErrorReasons');
            rejectionReasons = JSON.parse(rejectionReasons);
            //for reason Code and Business Process Stages
            switch (outcomeSelected) {
                case 'Resume Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'resume_trade';
                    break;

                case 'Settle Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'settle_trade';
                    break;

                case 'Confirm Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'confirm_trade';
                    break;

                case 'Process Trade Cancellation':
                    reasonCodeOutcome = 'Cancel';
                    bpiOutcome = 'process_trade_cancellation';
                    break;

                case 'Put Trade On-Hold':
                    reasonCodeOutcome = 'Put On Hold';
                    bpiOutcome = 'put_trade_on_hold';
                    break;

            }
            //for reason Code and Business Process Stages

            //getting the attachment
            var getTempAttachment = new GlideRecord("sys_attachment");
            getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
            getTempAttachment.orderByDesc('sys_created_on');
            getTempAttachment.query();
            if (getTempAttachment.next()) {

                var attachmentSysId = getTempAttachment.getValue('sys_id');
                var attachmentName = getTempAttachment.getValue('file_name'); // MSSCUSTODY 6700 - Fetching file size and type
                var attachmentSize = getTempAttachment.getValue('size_bytes'); // MSSCUSTODY 6700 - Fetching file size and type

                // Validate file type
                if (!attachmentName.endsWith('.xlsx')) {
                    bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Result Retured Invalid file type' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return "Invalid file type";
                }

                // Validate file size
                if (attachmentSize > (10 * 1024 * 1024)) {
                    bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Result Retured File size exceeded' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return "File size exceeded";
                }
            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(attachmentSysId); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetNumber(0); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }

            //gs.info('Bulk Validation File read - Completion for 500 records at ' + new GlideDateTime().getDisplayValue());


            if (bulkexcelRowArray.length > 0) {
                //gs.info('Bulk Validation Evaluation started for 500 records at ' + new GlideDateTime().getDisplayValue());


                for (var i = 0; i < bulkexcelRowArray.length; i++) {

                    (function executeRow(index) {

                        var getData = JSON.parse(bulkexcelRowArray[i]);
                        //Inputs from Excel
                        var trdRef = getData.tradeReference; //Change name as per Excel Sheet
                        //Inputs from Excel
                        var trdMarket = owningBusiness.toString(); //paramter from record producer

                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Received Trade Reference before modification ' + trdRef + 'Selected market ' + trdMarket + ' ' + '\n'); //optimiser 2511050923036567

                        if (trdRef != null && trdRef != undefined && trdRef != '') { //ignoring all null trade references

                            trdRef = new x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload().handleTradeReference(trdRef, trdMarket);

                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Received Trade Reference after modification ' + trdRef + 'Selected market ' + trdMarket + ' ' + '\n'); //optimiser 2511050923036567


                            var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                            getTradeData.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business=' + trdMarket + '^case_type=no_open_case' + '^trade_lifecycle_status!=TradSttld^trade_lifecycle_status!=TradCanc');
                            getTradeData.query();
                            if (getTradeData.next()) {

                                var countOfTrades = parseInt(getTradeData.getRowCount());

                                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Count of records for  ' + trdRef + ' and Selected market ' + trdMarket + ' ' + countOfTrades + '\n'); //optimiser 2511050923036567


                                if (countOfTrades == 1) { //Valid Records Count == 1

                                    var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                                    grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + owningBusiness + '^ctac_code=' + getTradeData.trade_lifecycle_status + '^' + bpiOutcome + '=true');
                                    grBulkEvents.setLimit(1);
                                    grBulkEvents.query();
                                    if (grBulkEvents.next()) {
                                        validRecords.push(getTradeData.sys_id.toString() + '');

                                    } else { //Business process is not enabled
                                        //Error Records

                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Business process is not enabled for   ' + getTradeData.trade_lifecycle_status + ' reference ' + trdRef + ' and Selected market ' + trdMarket + ' ' + countOfTrades + '\n'); //optimiser 2511050923036567

                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = outcomeSelected + ' is not enabled for Life Cycle Status ' + getTradeData.trade_lifecycle_status.getDisplayValue(); //duplicateTrades
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records

                                    }


                                } else { //Duplicate Trades Count >1
                                    //Error Records
                                    errorObj.tradeRef = trdRef.toString();
                                    errorObj.tradeMarket = trdMarket.toString();
                                    errorObj.inValidReason = rejectionReasons.duplicateTrades.toString(); //duplicateTrades
                                    errorRecords.push(JSON.stringify(errorObj) + ' ');
                                    //Error Records
                                }


                            } else {
                                //Invalid Trade Reference
                                var inValidTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                                inValidTrade.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business=' + trdMarket); // MSSCUSTODY-8253 Added owning business
                                inValidTrade.query();
                                if (inValidTrade.next()) {


                                    // Commented as part of MSSCUSTODY-8253
                                    //Valid trade reference but belongs to different market than selected
                                    /*if (inValidTrade.owning_business.toString() != trdMarket.toString()) {

                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' invalidMarket Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Trade market ' + inValidTrade.owning_business + '\n'); //optimiser 2511050923036567


                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.invalidMarket.toString(); //different market than record producer
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');

                                    }*/
                                    if (inValidTrade.case_type.toString() != 'no_open_case') { //Has Active Case 

                                        //bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' no_open_case Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Type of Case ' + inValidTrade.case_type.toString() + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.activeOpenCase.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records

                                    } else if (inValidTrade.trade_lifecycle_status == 'TradSttld') {

                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Trade Settled Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Life Cycle ' + inValidTrade.trade_lifecycle_status + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.tradeSettled.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records


                                    } else if (inValidTrade.trade_lifecycle_status == 'TradCanc') {

                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Trade Cancelled Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Life Cycle ' + inValidTrade.trade_lifecycle_status + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.tradeCancelled.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records


                                    }
                                } else { //InValid trade reference not avialable with reference to iQube
                                    // Commented as part of MSSCUSTODY-8253
                                    /*bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' unAvailableTrade Category ' + trdRef + 'Selected market ' + trdMarket + '\n'); //optimiser 2511050923036567
                                    errorObj.tradeRef = trdRef.toString();
                                    errorObj.tradeMarket = trdMarket.toString();
                                    errorObj.inValidReason = rejectionReasons.unAvailableTrade.toString(); // not available in database
                                    errorRecords.push(JSON.stringify(errorObj) + ' ');*/

                                    // MSSCUSTODY-8253 - Additional check for trade reference in any market
                                    var notAvailable = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                                    notAvailable.addEncodedQuery('transaction_reference=' + trdRef);
                                    notAvailable.query();
                                    if (notAvailable.next()) {
                                        if (notAvailable.owning_business.toString() != trdMarket.toString()) {


                                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' invalidMarket Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Trade market ' + notAvailable.owning_business + '\n');
                                            errorObj.tradeRef = trdRef.toString();
                                            errorObj.tradeMarket = trdMarket.toString();
                                            errorObj.inValidReason = rejectionReasons.invalidMarket.toString();
                                            errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        }
                                    } else {
                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' unAvailableTrade Category ' + trdRef + 'Selected market ' + trdMarket + '\n');
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.unAvailableTrade.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                    }
                                }

                            }

                        }
                    })(i);

                }

                //Trade Life Cycle Status dynamically sending to the record producer

                //gs.info('Bulk Validation Evaluation Completed for 500 records at ' + new GlideDateTime().getDisplayValue());


                errorData = filterArray.unique(errorRecords);

                var summaryTotalCount = parseInt(errorRecords.length) + parseInt(validRecords.length);
                var summaryErrorRecords = parseInt(errorRecords.length);
                var summaryValidRecords = parseInt(validRecords.length);
                var finalErrorRate = (summaryErrorRecords / summaryTotalCount) * 100; // converting to percentage


                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Total Records ' + summaryTotalCount + '\n');
                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Error Records ' + summaryErrorRecords + '\n');
                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Valid Records ' + summaryValidRecords + '\n');
                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Error Rate ' + errorRate + '\n');
                bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Error Percentage of records ' + finalErrorRate + '%' + '\n');

                if (summaryTotalCount == 0) { //unable to read due to any file error

                    bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered Invalid Entries Loop ' + '\n');
                    bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered Invalid Entries Loop ' + ' Result Retured = Invalid Entries' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return 'Invalid Entries' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; //data of errors
                }

                if ((summaryTotalCount > 0) && (summaryTotalCount < maxLimit)) {

                    if ((summaryErrorRecords > 0) && (summaryTotalCount > 0)) {

                        if (finalErrorRate > errorRate) { //More that 10% errors

                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered more than 10% Error Loop ' + '\n');
                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered more than 10% Error Loop ' + ' Result Retured = Validation Failed' + '\n');
                            if (bulkUploadErrorLogs) { //Log for debugging
                                gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                            }
                            return 'Validation Failed' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; //data of errors

                        } else { //Less that 50% errors
                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered less than 10% Error Loop ' + '\n');
                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + 'Entered less than 10% Error Loop ' + ' Result Retured =  Validation Successful' + '\n');
                            if (bulkUploadErrorLogs) { //Log for debugging
                                gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                            }
                            return 'Validation Successful' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; ///data of errors;

                        }

                    } else { //No errors

                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + ' Result Retured = No Errors' + '\n');
                        if (bulkUploadErrorLogs) { //Log for debugging
                            gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                        }
                        return 'No Errors' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; ///data of errors;
                    }

                } else {

                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Bulk File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return 'Limit Exceeded' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData;

                }


            }
            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' Result Retured = No records Found' + '\n');
            if (bulkUploadErrorLogs) { //Log for debugging
                gs.info("Bulk File Upload by " + currentUser + '\n' + bulkFileUploadLogs.toString());
            }
            return 'No records Found'; //empty file

        } catch (ex) {
            gs.info('Error Received from bulkLevelParse Client' + ex);
        }
    },

    //Bulk Level File Upload




    //Trade Level Fil Upload
    validateTradeFileUpload: function() {

        /* The array of invalid trades received from bulkErrorValidation 
        will be utilized to populate the new field(TBD) in submitted bulk which will be utilized for the display of audit log*/

        try {
            var owningBusiness = this.getParameter('sysparm_market');
            var outcomeSelected = this.getParameter('sysparm_outcome');
            var bulkexcelRowArray = [];
            var errorObj = {};
            var validObj = {};
            var errorRecords = [];
            var validRecords = [];
            var bulkFileUploadLogs = [];
            var count = 0;
            var filterArray = new global.ArrayUtil();
            var reasonCodeOutcome = '';
            var bpiOutcome = '';
            var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
            var errorRate = parseFloat(gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadErrorRateAcceptance'));
            var maxLimit = parseInt(gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadMaxUploadLimit'));
            var bulkUploadErrorLogs = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadLogs');
            var rejectionReasons = gs.getProperty('x_hsb11_hsbc_mss_o.bulkFileUploadErrorReasons');
            rejectionReasons = JSON.parse(rejectionReasons);


            //for reason Code and Business Process Stages
            switch (outcomeSelected) {
                case 'Resume Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'resume_trade';
                    break;

                case 'Settle Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'settle_trade';
                    break;

                case 'Confirm Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'confirm_trade';
                    break;

                case 'Process Trade Cancellation':
                    reasonCodeOutcome = 'Cancel';
                    bpiOutcome = 'process_trade_cancellation';
                    break;

                case 'Put Trade On-Hold':
                    reasonCodeOutcome = 'Put On Hold';
                    bpiOutcome = 'put_trade_on_hold';
                    break;

            }
            //for reason Code and Business Process Stages

            //getting the attachment
            var getTempAttachment = new GlideRecord("sys_attachment");
            getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
            getTempAttachment.orderByDesc('sys_created_on');
            getTempAttachment.query();
            if (getTempAttachment.next()) {

                var attachmentSysId = getTempAttachment.getValue('sys_id');
                var attachmentName = getTempAttachment.getValue('file_name'); // MSSCUSTODY 6700 - Fetching file size and type
                var attachmentSize = getTempAttachment.getValue('size_bytes'); // MSSCUSTODY 6700 - Fetching file size and type

                // Validate file type
                if (!attachmentName.endsWith('.xlsx')) {
                    bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Result Retured Invalid file type' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return "Invalid file type";
                }

                // Validate file size
                if (attachmentSize > (10 * 1024 * 1024)) {
                    bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Result Retured File size exceeded' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return "File size exceeded";
                }
            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(attachmentSysId); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetNumber(0); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }


            if (bulkexcelRowArray.length > 0) {

                for (var i = 0; i < bulkexcelRowArray.length; i++) {

                    (function executeRow(index) {

                        var getData = JSON.parse(bulkexcelRowArray[i]);
                        //Inputs from Excel
                        var trdRef = getData.tradeReference ? getData.tradeReference.trim() : ""; //Change name as per Excel Sheet
                        var reasonCode = getData.reasonCode ? getData.reasonCode.trim() : ""; //reason Code
                        //Inputs from Excel
                        var trdMarket = owningBusiness.toString(); //paramter from record producer

                        bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Received Trade Reference before modification ' + trdRef + 'Selected market ' + trdMarket + ' ' + '\n'); //optimiser 2511050923036567



                        if (trdRef != null && trdRef != undefined && trdRef != '') { //ignoring all null trade references

                            //Handling trade Reference Format
                            trdRef = new x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload().handleTradeReference(trdRef, trdMarket);
                            //Handling Trade Reference Format

                            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Received Trade Reference after modification ' + trdRef + 'Selected market ' + trdMarket + ' ' + '\n'); //optimiser 2511050923036567


                            //reason code modification
                            if ((reasonCode != "") && (reasonCode != undefined) && (reasonCode != null)) {
                                var modifiedReasonCode = reasonCode.split('-')[0].trim().toString();
                            } else {
                                modifiedReasonCode = 'NOT AVAILABLE';
                            }
                            //reason code modification

