                                            errorObj.tradeRef = trdRef.toString();
                                            errorObj.tradeMarket = trdMarket.toString();
                                            errorObj.inValidReason = modifiedReasonCode + " reason code does not exist for " + outcomeSelected; //duplicateTrades
                                            errorRecords.push(JSON.stringify(errorObj) + ' ');
                                            //Error Records
                                        }



                                    } else { //Business process is not enabled
                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = outcomeSelected + ' is not enabled for Life Cycle Status ' + getTradeData.trade_lifecycle_status.getDisplayValue(); //duplicateTrades
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
