                                    //Error Records
                                    errorObj.tradeRef = trdRef.toString();
                                    errorObj.tradeMarket = trdMarket.toString();
                                    errorObj.inValidReason = rejectionReasons.duplicateTrades.toString(); //duplicateTrades
                                    errorRecords.push(JSON.stringify(errorObj) + ' ');
                                    //Error Records
                                }


                            } else {
                                //Invalid Trade Reference
                                var inValidTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                                inValidTrade.addEncodedQuery('transaction_reference=' + trdRef);
                                inValidTrade.query();
                                if (inValidTrade.next()) {

                                    //bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Invalid Trade Reference Start ' + trdRef + 'Selected market ' + trdMarket + ' ' + '\n'); //optimiser 2511050923036567

                                    // Commented as part of MSSCUSTODY-8253
                                    //Valid trade reference but belongs to different market than selected
                                    // if (inValidTrade.owning_business.toString() != trdMarket.toString()) {

                                    //     bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' invalidMarket Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Trade market ' + inValidTrade.owning_business + '\n'); //optimiser 2511050923036567

                                    //     errorObj.tradeRef = trdRef.toString();
                                    //     errorObj.tradeMarket = trdMarket.toString();
                                    //     errorObj.inValidReason = rejectionReasons.invalidMarket.toString(); //different market than record producer
                                    //     errorRecords.push(JSON.stringify(errorObj) + ' ');

                                    // } 
                                    if (inValidTrade.case_type.toString() != 'no_open_case') { //Has Active Case 

                                        bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' no_open_case Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Type of Case ' + inValidTrade.case_type.toString() + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.activeOpenCase.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records

                                    } else if (inValidTrade.trade_lifecycle_status == 'TradSttld') {

                                        bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Trade Settled Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Life Cycle ' + inValidTrade.trade_lifecycle_status + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.tradeSettled.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records


                                    } else if (inValidTrade.trade_lifecycle_status == 'TradCanc') {


                                        bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Trade Cancelled Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Case Life Cycle ' + inValidTrade.trade_lifecycle_status + '\n'); //optimiser 2511050923036567

                                        //Error Records
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.tradeCancelled.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        //Error Records


                                    }
                                } else { //InValid trade reference not avialable with reference to iQube
                                    /*bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' unAvailableTrade Category ' + trdRef + 'Selected market ' + trdMarket + '\n'); //optimiser 2511050923036567

                                    errorObj.tradeRef = trdRef.toString();
                                    errorObj.tradeMarket = trdMarket.toString();
                                    errorObj.inValidReason = rejectionReasons.unAvailableTrade.toString(); // not available in database
                                    errorRecords.push(JSON.stringify(errorObj) + ' ');*/

                                    var notAvailable = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                                    notAvailable.addEncodedQuery('transaction_reference=' + trdRef);
                                    notAvailable.query();
                                    if (notAvailable.next()) {
                                        if (notAvailable.owning_business.toString() != trdMarket.toString()) {
                                            bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' invalidMarket Category ' + trdRef + 'Selected market ' + trdMarket + ' ' + 'Trade market ' + notAvailable.owning_business + '\n');
                                            errorObj.tradeRef = trdRef.toString();
                                            errorObj.tradeMarket = trdMarket.toString();
                                            errorObj.inValidReason = rejectionReasons.invalidMarket.toString();
                                            errorRecords.push(JSON.stringify(errorObj) + ' ');
                                        }
                                    } else {
                                        bulkFileUploadLogs.push('Bulk File Upload for attachment =' + attachmentSysId + " " + ' unAvailableTrade Category ' + trdRef + 'Selected market ' + trdMarket + '\n');
                                        errorObj.tradeRef = trdRef.toString();
                                        errorObj.tradeMarket = trdMarket.toString();
                                        errorObj.inValidReason = rejectionReasons.unAvailableTrade.toString();
                                        errorRecords.push(JSON.stringify(errorObj) + ' ');
                                    }
                                }

                            }

                        }
                    })(i);

                }


                //Trade Life Cycle Status dynamically sending to the record producer

                errorData = filterArray.unique(errorRecords);

                var summaryTotalCount = parseInt(errorRecords.length) + parseInt(validRecords.length);
                var summaryErrorRecords = parseInt(errorRecords.length);
                var summaryValidRecords = parseInt(validRecords.length);
                var finalErrorRate = (summaryErrorRecords / summaryTotalCount) * 100; // converting to percentage

                bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Total Records ' + summaryTotalCount + '\n');
                bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Error Records ' + summaryErrorRecords + '\n');
                bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Valid Records ' + summaryValidRecords + '\n');
                bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Error Rate ' + errorRate + '\n');
                bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Error Percentage of records ' + finalErrorRate + '%' + '\n');


                if (summaryTotalCount == 0) { //unable to read due to any file error

                    bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered Invalid Entries Loop ' + '\n');
                    bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered Invalid Entries Loop ' + ' Result Retured = Invalid Entries' + '\n');
                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return 'Invalid Entries' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; //data of errors
                }

                if ((summaryTotalCount > 0) && (summaryTotalCount < maxLimit)) {

                    if ((summaryErrorRecords > 0) && (summaryTotalCount > 0)) {

                        if (finalErrorRate > errorRate) { //More that 10% errors

                            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered more than 10% Error Loop ' + '\n');
                            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered more than 10% Error Loop ' + ' Result Retured = Validation Failed' + '\n');
                            if (bulkUploadErrorLogs) { //Log for debugging
                                gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                            }
                            return 'Validation Failed' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; //data of errors

                        } else { //Less that 50% errors
                            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered less than 10% Error Loop ' + '\n');
                            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + 'Entered less than 10% Error Loop ' + ' Result Retured =  Validation Successful' + '\n');
                            if (bulkUploadErrorLogs) { //Log for debugging
                                gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                            }
                            return 'Validation Successful' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; ///data of errors;

                        }

                    } else { //No errors

                        bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + ' Result Retured = No Errors' + '\n');
                        if (bulkUploadErrorLogs) { //Log for debugging
                            gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                        }
                        return 'No Errors' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData; ///data of errors;
                    }

                } else {

                    if (bulkUploadErrorLogs) { //Log for debugging
                        gs.info("Trade File Upload " + '\n' + bulkFileUploadLogs.toString());
                    }
                    return 'Limit Exceeded' + "/" + summaryTotalCount + "/" + summaryErrorRecords + "/" + summaryValidRecords + "/" + errorData;

                }


            }
            bulkFileUploadLogs.push('Trade File Upload for attachment =' + attachmentSysId + " " + ' Result Retured = No records Found' + '\n');
            if (bulkUploadErrorLogs) { //Log for debugging
                gs.info("Trade File Upload by " + currentUser + '\n' + bulkFileUploadLogs.toString());
            }
            return 'No records Found'; //empty file

        } catch (ex) {
            gs.info('Error Received from TradeLevel Client' + ex);
        }
    },

