    createCreateBulkCaseBulkFielUpload: function(bulkRecID, owningBusiness, tskoutcome) { //used in on submit of record producer

        try {

            //table_nameSTARTSWITHZZ_YYx_hsb11_hsbc_mss_o_hsbc_bulk_transaction^sys_created_bySTARTSWITH45381533@hsbc.com

            var bulkexcelRowArray = [];
            var validRecords = [];
            var filterArray = new global.ArrayUtil();
            var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
            var getOwningBusiness = new GlideRecord('sys_user_group_type');
            getOwningBusiness.get(owningBusiness);
            var market = getOwningBusiness.name;
            var bpiOutcome = "";

            tskoutcome = tskoutcome.toString().trim();

            gs.info('Bulk File Upload Array Trade Received Outcome from RP' + tskoutcome);
            gs.info('Bulk File Upload Array Trade Received Outcome from RP' + typeof(tskoutcome));


            gs.info('Bulk File Upload Array Trade Received Outcome from RP after trimming' + tskoutcome);


            switch (tskoutcome) {
                case 'Resume Trade':
                    bpiOutcome = 'resume_trade';
                    break;

                case 'Settle Trade':
                    bpiOutcome = 'settle_trade';
                    break;

                case 'Confirm Trade':
                    bpiOutcome = 'confirm_trade';
                    break;

                case 'Process Trade Cancellation':
                    bpiOutcome = 'process_trade_cancellation';
                    break;

                case 'Put Trade On-Hold':
                    bpiOutcome = 'put_trade_on_hold';
                    break;

            }

            gs.info('Bulk File Upload Array Trade Received Outcome ' + tskoutcome + ' BPIOutcome converted to ' + bpiOutcome);

            //getting the attachment
            var bulkgetAttachment = new GlideRecord('sys_attachment');
            bulkgetAttachment.addEncodedQuery('table_nameSTARTSWITHZZ_YY^sys_created_bySTARTSWITH' + currentUser);
            bulkgetAttachment.orderByDesc('sys_created_on');
            bulkgetAttachment.query();
            if (bulkgetAttachment.next()) {
                var bulkattachmentRec = bulkgetAttachment.getValue('sys_id');

            }
            //getting attachment

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(bulkattachmentRec); //getting content of the EXcel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetNumber(0); //setting the first shee to parse

            if (bulkparser.parse()) { //converting into readable format using parse

                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = market.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma sepearated
                    bulkexcelRowArray.push(bulkrowObj + '');

                }
            }

            //find only validrecords

            for (var i = 0; i < bulkexcelRowArray.length; i++) {

                (function executeRow(index) {

                    var getData = JSON.parse(bulkexcelRowArray[i]);
                    var trdRef = getData.tradeReference; //Change name as per Excel Sheet

                    if (trdRef != null && trdRef != undefined && trdRef != '') { //ignoring all null trade references

                        var trdMarket = getData.business.toString(); //Change name as per Excel Sheet
                        //Handling trade Reference Format
                        trdRef = new x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload().handleTradeReference(trdRef, trdMarket);
                        //Handling Trade Reference Format

                        var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                        getTradeData.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business=' + trdMarket + '^case_type=no_open_case' + '^trade_lifecycle_status!=TradSttld^trade_lifecycle_status!=TradCanc');
                        getTradeData.query();
                        if (getTradeData.next()) {

                            var countOfTrades = parseInt(getTradeData.getRowCount());

                            if (countOfTrades == 1) { //Valid Records Count == 1

                                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + owningBusiness + '^ctac_code=' + getTradeData.trade_lifecycle_status + '^' + bpiOutcome + '=true');
                                grBulkEvents.setLimit(1);
                                grBulkEvents.query();
                                if (grBulkEvents.next()) {
                                    validRecords.push(getTradeData.sys_id.toString() + '');

                                }
                            }
                        }

                    }
                })(i);

            }

            //find only validrecords

            validRecords = filterArray.unique(validRecords); //unique records

            //write function to create case and link to bulk


            var tradeCount = validRecords.length;
            var threshold = gs.getProperty('x_hsb11_mss_c_proc.bulk_threshold_event_queue');
            var uploadtype = 'bulk_level';
            var parm1 = bulkRecID + '|' + tskoutcome + '/' + uploadtype + '@' + owningBusiness;


            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addQuery('sys_id', 'IN', validRecords.join(','));
            grCustodyTrade.query();

            if (parseInt(tradeCount, 10) > parseInt(threshold, 10) && gs.getProperty('x_hsb11_mss_c_proc.BulkEventQueue') == 'true') {
                //If number of trades in the bulk is larger than threshold, use asyn event queue approach
                var tradesArray = [],
                    i = 0,
                    tradesInSingleEvt = gs.getProperty('x_hsb11_mss_c_proc.number_of_items_in_bulk_event'); //number of trades to be processed via a single event for case creation

                while (grCustodyTrade.next()) {
                    tradesArray.push(grCustodyTrade.sys_id.toString());
                    i++;
                    if (i == tradesInSingleEvt) {
                        gs.eventQueue("x_hsb11_hsbc_mss_o.upload_case_creation", null, parm1, tradesArray.join(','));
                        //reset to initial
                        i = 0;
                        tradesArray = [];
                    }
                }

                //create event for the remainings after loop completes
                if (i > 0) {
                    gs.eventQueue("x_hsb11_hsbc_mss_o.upload_case_creation", null, parm1, tradesArray.join(','));
                }

            } else {

                for (var j = 0; j < validRecords.length; j++) {
                    var tradeSysId = validRecords[j];

                    // Update the trade record
                    var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    if (grcustodytrade.get(tradeSysId)) {
                        grcustodytrade.case_type = 'manual';
                        grcustodytrade.update();
                    }

                    // Create the custody case
                    var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                    grcustodycase.initialize();
                    grcustodycase.reinitiate_process = false;
                    grcustodycase.state = 1;
                    grcustodycase.short_description = 'Manually triggered by Bulk processing';
                    grcustodycase.description = 'Manually triggered by Bulk processing';
                    grcustodycase.trade_id = tradeSysId;
                    grcustodycase.bulk_id = bulkRecID; // Use the bulk record ID passed to the function
                    grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5'; // Static sys_id as per your logic
                    grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                    grcustodycase.insert();

                    var caseObj = grcustodycase;
                    var caseRec = grcustodycase.sys_id;


                    try {
                        var inputs = {};
                        inputs['current'] = caseObj; // GlideRecord of table: 
                        inputs['table_name'] = 'x_hsb11_mss_c_proc_mss_custody_case';
                        var flowName = 'x_hsb11_mss_c_proc.hsbccustodymanual_bulk_task_generic_flow';

                        // Starts the flow asynchronously.
                        var contextId = sn_fd.FlowAPI.startFlow(flowName, inputs);

                        //Identifier for the flow context
                        var updateCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                        updateCase.get(caseRec);
                        updateCase.work_notes = 'Flow Executed for the bulk File Upload with Execution ID ' + contextId;
                        updateCase.update();
                        //Identifier for the flow context


                    } catch (ex) {
                        //var message = ex.getMessage();
                        gs.info("Error Triggering Manual Flow ABCD " + ex.message);
                    }


                }
            }



            return validRecords.length;



        } catch (ex) {
            gs.info('Error Received from createCreateBulkCaseBulkFielUpload ' + ex);
        }

    },


    createBulkCaseTradeFileUpload: function(bulkRecID, owningBusiness, outcome) { //used on submit of record producer

        try {
            // MSSCUSTODY-6821
            var bulkexcelRowArray = [];
            var validObj = {};
            var caseArr = [];
            var validRecords = [];
            var reasonCodeOutcome = '';
            var filterArray = new global.ArrayUtil();
            var currentUser = gs.getUser().getName(); //to fetch the right attachment by user
            var modifiedReasonCode;

            outcome = outcome.toString().trim();

            gs.info('Trade File Upload Array Trade Received Outcome from RP' + outcome);
            gs.info('Trade File Upload Array Trade Received Outcome from RP' + typeof(outcome));


            gs.info('Trade File Upload Array Trade Received Outcome from RP after trimming' + outcome);


            var bpiOutcome = "";


            switch (outcome) {
                case 'Resume Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'resume_trade';
                    break;

                case 'Settle Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'settle_trade';
                    break;

                case 'Confirm Trade':
                    reasonCodeOutcome = 'NA';
                    bpiOutcome = 'confirm_trade';
                    break;

                case 'Process Trade Cancellation':
                    reasonCodeOutcome = 'Cancel';
                    bpiOutcome = 'process_trade_cancellation';
                    break;

                case 'Put Trade On-Hold':
                    reasonCodeOutcome = 'Put On Hold';
                    bpiOutcome = 'put_trade_on_hold';
                    break;

            }

            gs.info('Trade File Upload Array Trade Received Outcome ' + outcome + ' BPIOutcome converted to ' + bpiOutcome);


            //getting attachment
            var getTempAttachment = new GlideRecord("sys_attachment");
            getTempAttachment.addEncodedQuery("table_name=ZZ_YYsc_cart_item^sys_created_by=" + currentUser);
            getTempAttachment.orderByDesc('sys_created_on');
            getTempAttachment.query();
            if (getTempAttachment.next()) {
                var attachmentSysId = getTempAttachment.getValue('sys_id');
            }

            var bulkattachment = new GlideSysAttachment(); //method to get the contents of the attachment
            var bulkattachmentDetails = bulkattachment.getContentStream(attachmentSysId); //getting content of the Excel

            var bulkparser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
            bulkparser.setSource(bulkattachmentDetails); //setting the source to parse the content from the stream

            var bulkgetSheet = bulkparser.getSheetNames(); //getting the sheet name to fetch details
            bulkparser.setSheetNumber(0); //setting the sheet to parse

            if (bulkparser.parse()) { //converting into readable format using parse
                while (bulkparser.next()) { //iterating over each row
                    var bulkgetRows = bulkparser.getRow(); //reading row by row
                    bulkgetRows.business = owningBusiness.toString(); //add the owning business for each array item which will be used for error validation which will be from record producer
                    var bulkrowObj = JSON.stringify(bulkgetRows); //holds the rows of Excel as comma separated
                    bulkexcelRowArray.push(bulkrowObj + '');
                }
            }

            gs.info('Ttotal Array Trade ' + bulkexcelRowArray.toString());

            if (bulkexcelRowArray.length > 0) {

                for (var i = 0; i < bulkexcelRowArray.length; i++) {

                    (function executeRow(index) {

                        var getData = JSON.parse(bulkexcelRowArray[i]); //Inputs from Excel
                        var trdRef = getData.tradeReference ? getData.tradeReference.trim() : ""; //trade reference
                        var reasonCode = getData.reasonCode ? getData.reasonCode.trim() : ""; //reason Code
                        var reasonDesc = getData.reasonDescription;
                        if (outcome == 'Process Trade Cancellation') {
                            var cancellationRef = getData.cancellationReference ? getData.cancellationReference : "";
                        }


                        if (trdRef != null && trdRef != undefined && trdRef != '') { //ignoring all null trade references

                            var trdMarket = owningBusiness.toString(); //owning business
                            //Handling trade Reference Format
                            trdRef = new x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload().handleTradeReference(trdRef, trdMarket);
                            //Handling Trade Reference Format

                            //reason code modification
                            if ((reasonCode != "") && (reasonCode != undefined) && (reasonCode != null)) {
                                modifiedReasonCode = reasonCode.split('-')[0].trim().toString();
                            } else {
                                modifiedReasonCode = 'NOT AVAILABLE';
                            }
                            //reason code modification


                            var getTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                            getTradeData.addEncodedQuery('transaction_reference=' + trdRef + '^owning_business=' + trdMarket + '^case_type=no_open_case' + '^trade_lifecycle_status!=TradSttld^trade_lifecycle_status!=TradCanc');
                            getTradeData.query();
                            if (getTradeData.next()) {
                                gs.info('Trade File Upload ' + 'business_process.process_name=Trade Lifecycle Status^market=' + owningBusiness + '^ctac_code=' + getTradeData.trade_lifecycle_status + '^' + bpiOutcome + '=true');

                                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + owningBusiness + '^ctac_code=' + getTradeData.trade_lifecycle_status + '^' + bpiOutcome + '=true');
                                grBulkEvents.setLimit(1);
                                grBulkEvents.query();
                                if (grBulkEvents.next()) { //added as part of active trade count mismatch

                                    var countOfTrades = parseInt(getTradeData.getRowCount());

                                    if (countOfTrades == 1) { //Valid Records Count == 1

                                        //Checking if the Reason Code Provided Exisits 
                                        var getReasonCode = new GlideRecord("x_hsb11_mss_c_proc_custody_reason_code");
                                        getReasonCode.addEncodedQuery("owning_business=" + trdMarket + "^reason_codeSTARTSWITH" + modifiedReasonCode + '^reason_code_type=' + reasonCodeOutcome); //new line
                                        getReasonCode.setLimit(1);
                                        getReasonCode.query();
                                        if (getReasonCode.next()) {
                                            validObj.tradeReference = trdRef.toString();
                                            validObj.reasonCode = getReasonCode.sys_id.toString();

                                            if (reasonDesc != null && reasonDesc != undefined && reasonDesc != '') { //pick up Excel reason code
                                                validObj.reasonDescription = reasonDesc.toString();
                                            } else { //if empty then pick up from table
                                                validObj.reasonDescription = getReasonCode.reason_description.toString();
                                            }

                                            if (outcome == 'Process Trade Cancellation') {
                                                validObj.cancellationReference = cancellationRef.toString();
                                            }
                                            validRecords.push(JSON.stringify(validObj) + '');
                                        }
                                    }
                                }

                            }

                        }

                    })(i);

                }

                validRecords = filterArray.unique(validRecords);
                //gs.info('6821 File read completed: ' + new GlideDateTime());
            }

            var tradeCount = validRecords.length;
            var threshold = gs.getProperty('x_hsb11_mss_c_proc.bulk_threshold_event_queue');
            var uploadtype = 'trade_level';
            var parm1 = bulkRecID + '|' + outcome + '/' + uploadtype + '@' + owningBusiness;



            if (parseInt(tradeCount, 10) > parseInt(threshold, 10) && gs.getProperty('x_hsb11_mss_c_proc.BulkEventQueue') == 'true') {
                //If number of trades in the bulk is larger than threshold, use asyn event queue approach
                var tradesArray = [],
                    j = 0,
                    tradesInSingleEvt = gs.getProperty('x_hsb11_mss_c_proc.number_of_items_in_bulk_event');

                for (var idx = 0; idx < validRecords.length; idx++) {
                    tradesArray.push(validRecords[idx]);
                    j++;
                    if (j == tradesInSingleEvt) {
                        gs.eventQueue("x_hsb11_hsbc_mss_o.upload_case_creation", null, parm1, JSON.stringify(tradesArray));
                        j = 0;
                        tradesArray = [];
                    }
                }

                //create event for the remainings after loop completes
                if (j > 0) {
                    gs.eventQueue("x_hsb11_hsbc_mss_o.upload_case_creation", null, parm1, JSON.stringify(tradesArray));
                }
            } else {
                for (var l = 0; l < validRecords.length; l++) {

                    (function executeRow(index) {

                        var tradeRecords = JSON.parse(validRecords[l]);
                        var tradeSysId = tradeRecords.tradeReference;
                        var reasonCode = tradeRecords.reasonCode;
                        var reasonDescription = tradeRecords.reasonDescription;
                        if (outcome == 'Process Trade Cancellation') {
                            var cancellationReference = tradeRecords.cancellationReference;
                        }
                        // Update the trade record
                        var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                        grcustodytrade.addEncodedQuery('transaction_referenceSTARTSWITH' + tradeSysId + '^owning_business=' + owningBusiness);
                        grcustodytrade.setLimit(1);
                        grcustodytrade.query();
                        if (grcustodytrade.next()) {
                            grcustodytrade.case_type = 'manual';
                            grcustodytrade.update();
                            var tradeID = grcustodytrade.sys_id;
                        }

                        // Create the custody case
                        var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                        grcustodycase.initialize();
                        grcustodycase.reinitiate_process = false;
                        grcustodycase.state = 1;
                        grcustodycase.short_description = 'Manually triggered by Bulk processing';
                        grcustodycase.description = 'Manually triggered by Bulk processing';
                        grcustodycase.trade_id = tradeID;
                        grcustodycase.bulk_id = bulkRecID; // Use the bulk record ID passed to the function
                        grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5'; // Static sys_id
                        grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                        grcustodycase.insert();

                        var caseObj = grcustodycase;
                        var caseRec = grcustodycase.sys_id;

                        var caseArrObj = {};
                        caseArrObj.caseSysId = caseRec.toString();
                        caseArrObj.tradeSysId = tradeSysId.toString();
                        caseArrObj.reasonCode = reasonCode.toString();
                        caseArrObj.reasonDescription = reasonDescription.toString();
                        if (outcome == 'Process Trade Cancellation') {
                            caseArrObj.cancellationReference = cancellationReference.toString();
                        }
                        caseArr.push(caseArrObj);

                        try {
                            var inputs = {};
                            inputs['current'] = caseObj; // GlideRecord of table: 
                            inputs['table_name'] = 'x_hsb11_mss_c_proc_mss_custody_case';
                            var flowName = 'x_hsb11_mss_c_proc.hsbccustodymanual_bulk_task_generic_flow';
                            // Starts the flow asynchronously.
                            var contextId = sn_fd.FlowAPI.startFlow(flowName, inputs);
                            //Identifier for the flow context
                            var updateCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                            updateCase.get(caseRec);
                            updateCase.work_notes = 'Flow Executed for the bulk File Upload with Execution ID ' + contextId;
                            updateCase.update();
                            //Identifier for the flow context
                        } catch (ex) {
                            gs.info("Error triggering manual flow for Trade File upload:" + ex.message);
                        }

                    })(l);
                }
            }

            //gs.info('6821 case creation & flow trigger completed: ' + new GlideDateTime());

            // Updating the tasks with reason code and reason description
            while (caseArr.length > 0) {
                for (var k = 0; k < caseArr.length; k++) {
                    (function executeRow(index) {
                        var getData = caseArr[index]; // Parse the current case data
                        var tradeRef = getData.tradeSysId;
                        var caseRef = getData.caseSysId;
                        var reasonCode = getData.reasonCode;
                        var reasonDesc = getData.reasonDescription;
                        if (outcome == 'Process Trade Cancellation') {
                            var cancellationRef = getData.cancellationReference;
                        }
                        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                        grTask.addEncodedQuery('trade_case_id.sys_idSTARTSWITH' + caseRef + '^trade_id.transaction_referenceSTARTSWITH' + tradeRef + ' ^trade_task_type=Maker');
                        grTask.query();
                        if (grTask.next()) {
                            grTask.reason_code = reasonCode;
                            grTask.reason_description = reasonDesc;
                            if (outcome == 'Process Trade Cancellation') {
                                grTask.cancellation_reference = cancellationRef;
                            }
                            grTask.update();
                            caseArr.splice(index, 1);
                        }
                    })(k);
                }
            }
            //gs.info('6821 Task updation completed: ' + new GlideDateTime());
            // return once all tasks are updated
            return validRecords.length;

        } catch (ex) {
            gs.info('Error from createBulkCaseTradeFileUpload : ' + ex.message);
        }

    },


    createBulkCaseTask: function(validRecords, bulkRecID) {


        try {
            for (var i = 0; i < validRecords.length; i++) {



                (function createBulkCase(index) {
                    var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                    grcustodycase.initialize();
                    grcustodycase.short_description = 'Manually triggered by Bulk processing';
                    grcustodycase.description = 'Manually triggered by Bulk processing';
                    grcustodycase.trade_id = validRecords[i];
                    grcustodycase.bulk_id = bulkRecID;
                    grcustodycase.state = 2;
                    grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5';
                    grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                    var caseSysId = grcustodycase.insert();
                })(i);

            }

            //updating active Trade Count
            var updateBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            updateBulk.get(bulkRecID);
            updateBulk.active_trade_count = parseInt(validRecords.length);
            updateBulk.update();
            //updating active Trade Count
        } catch (ex) {
            gs.info('Error Received from createBulkCaseTask ' + ex);
        }

    },

    populateErrorRecord: function(errorRecords, bulkRecID) {

        /* The array of invalid trades received from bulkErrorValidation 
        will be utilized to populate the new field(TBD) in submitted bulk which will be utilized for the display of audit log*/

        try {

            var populateErrorBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            populateErrorBulk.get(bulkRecID);
            populateErrorBulk.error_flag = "[" + errorRecords.toString() + "]";
            populateErrorBulk.update();

        } catch (ex) {
            gs.info('Error Received from populateErrorRecord ' + ex);
        }
    },


    getAssignmentGroup: function(roleName, owningBusiness) {
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addQuery('user', gs.getUserID());
        grMember.addEncodedQuery('group.typeLIKE2269529d1b844650ff37eb14b24bcb19^group.typeLIKE' + owningBusiness + '^group.nameLIKEMaker');
        grMember.query();

        while (grMember.next()) {
            var grGroupRole = new GlideRecord('sys_group_has_role');
            grGroupRole.addQuery('group', grMember.group);
            grGroupRole.addQuery('role.name', 'x_hsb11_mss_custod.custody_maker');
            grGroupRole.orderByDesc('group.name');
            grGroupRole.query();
            if (grGroupRole.next()) {
                assignmentGroup = grGroupRole.group;
                break;
            }

        }
        return assignmentGroup;
    },

    selectTaskTemplate: function(tempNum) {
        var taskTemplate = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_template');
        taskTemplate.addQuery('template_id', tempNum);
        taskTemplate.query();
        if (taskTemplate.next()) {
            var tempContents = {
                "description": taskTemplate.getValue("template_description"),
                "shortDescription": taskTemplate.getValue("template_short_description")
            };
            return JSON.stringify(tempContents);
        }
    },





    getUserOwningBusiness: function() {

        var getUserData = new GlideRecord('sys_user');
        getUserData.get(gs.getUserID());

        //return getUserData.u_associated_business_markets.toString();

		//MSSCUSTODY - 8543
        var userMarketsRaw = getUserData.u_associated_business_markets.toString().split(','); // Fetch user associated markets 

        var unavailableMarketsRaw = gs.getProperty('x_hsb11_mss_c_proc.custody_swift_unavailable_markets', '').split(','); // Get unavailable markets from system property

        var userMarkets = [];
        for (var i = 0; i < userMarketsRaw.length; i++) {
            var market = userMarketsRaw[i].replace(/^\s+|\s+$/g, '');
            if (market !== '') {
                userMarkets.push(market);
            }
        }

        var unavailableMarkets = [];
        for (var j = 0; j < unavailableMarketsRaw.length; j++) {
            var unMarket = unavailableMarketsRaw[j].replace(/^\s+|\s+$/g, '');
            if (unMarket !== '') {
                unavailableMarkets.push(unMarket);
            }
        }
		// Filter out unavailable markets
        var filteredMarkets = [];
        for (var k = 0; k < userMarkets.length; k++) {
            if (unavailableMarkets.indexOf(userMarkets[k]) === -1) {
                filteredMarkets.push(userMarkets[k]);
            }
        }

        return filteredMarkets.join(',');


    },



    getBulkFileUploadRecordProducer: function() {

        try {
            return gs.getProperty('x_hsb11_hsbc_mss_o.hsbcBulkFileUploadRecordProducer');

        } catch (ex) {
            gs.info('Error Received from getBulkFileUploadRecordProducer ' + ex);
        }

    },
    type: 'MSSCustodyBulkFileUpload'
});
